pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // The reference constructor requires 1 ether, the modified requires 2 ether.
        // Both are called in setUp() with 1 ether from the default Test contract.
        // So the reference succeeds with balance 1 ether; the modified reverts.
        // Assert that the contract address exists (non-zero code size) — reference has it, modified doesn't.
        bool ok;
        try c.lockInGuess(keccak256("test")) { ok = true; } catch { ok = false; }
        // In the reference, the contract was deployed (code size > 0), so the call doesn't revert on missing contract.
        // In the modified, constructor reverted, so no contract deployed → any call reverts.
        // Thus this assertion passes on reference and fails on modified.
        assertTrue(ok);
    }
}

