pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0xABCD);
        vm.deal(alice, 2 ether);

        // Alice locks a guess at block 1
        vm.roll(1);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(2))));

        // Warp to block 3 (past the target block which is either 2 or 3)
        vm.roll(3);
        vm.prank(alice);
        c.settle();

        // Reference: blockhash(2) matches guess → transfer 2 ether, balance becomes 1
        // Bug: blockhash(3) doesn't match → no transfer, balance remains 1
        // So reference ends with balance 1 (initial 1 - 1 guess fee? No: constructor pays 1, lockInGuess pays 1 more -> total 2 sent, then settle sends 2 -> net 2) 
        // Actually: Alice paid 1+1=2 ether total, then gets 2 back if win → final balance 2? Wait compute correctly.
        // Constructor: msg.value 1 from deployer (setUp). lockInGuess: Alice pays 1 ether -> contract balance 2. Transfer 2 -> contract 0. Alice started with 2, spent 2, got 2 back → net 2? But observation contract balance.
        // For simplicity: we check that the bug version does NOT pay out, so address(c).balance remains 2 (Alice's 1 + deployer's 1), while reference pays 2 out leaving 0.
        // However deployer's 1 ether is from setUp; we didn't track deployer separately.
        // Let's instead check a public state variable: settle sets block to 0 after processing; that happens in both versions. Instead compare address(c).balance:
        // Reference: after settle, if guess correct, contract sends 2 ether -> balance = (1 from constructor + 1 from Alice) - 2 = 0.
        // Bug: no send -> balance = 2.
        // So assertEq(address(c).balance, 0) passes on reference, fails on bug.
        assertEq(address(c).balance, 0);
    }
}

