pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the contract with 1 ether from deploy already done in constructor
        // Deal ether to player
        address player = address(0xABCD);
        vm.deal(player, 1 ether);

        // Player locks in a guess: keccak256 of blockhash of future block
        // We will call lockInGuess at block N, target block = N+1 (reference) or N+2 (buggy)
        // We warp to block 10 (arbitrary)
        vm.warp(10);
        vm.roll(10);

        bytes32 guess = keccak256(abi.encodePacked(blockhash(11))); // will be 0 because block 11 doesn't exist yet

        vm.prank(player);
        c.lockInGuess{value: 1 ether}(guess);

        // Move to next block (block 11) for the reference version; buggy version requires block 12
        vm.warp(11);
        vm.roll(11);

        // Call settle; catch revert if any
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        // The reference version: blockhash(11) is 0 in tests, guess is 0, so player wins and gets 2 ether => contract balance becomes 0 (initial 1 + 1 - 2 = 0)
        // The buggy version: blockhash(12) = 0, guess = 0, still wins but block = block.number + 2 was set, so settle() first require(block.number > 12) fails because block.number is only 11 => revert
        // So reference: ok = true, contract balance = 0
        // Buggy: ok = false, contract balance = 2 (initial 1 + 1 = 2, no transfer)
        assertEq(address(c).balance, 0);
    }
}

