import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the user with 3 ether to make two 1-eth deposits
        address user = address(0x1234);
        vm.deal(user, 3 ether);

        // First lockInGuess: succeeds in both versions (block == 0 in reference, block != 0 would fail in bug if we didn't adjust — but in reference it passes)
        // Actually for the reference: first call requires block == 0, so it passes.
        // For the buggy version: first call requires block != 0 — but block is 0 initially, so it would revert on first call!
        // To have the test fail the assertion (not an uncaught revert), we need the call to succeed in reference and fail in buggy.

        // So: first call in the reference works; first call in the buggy version would revert.
        // We need to catch the revert in the second version.

        bytes32 hash1 = keccak256("guess1");
        vm.prank(user);
        // Use try/catch to catch revert if it happens (buggy version will revert on first call)
        bool ok1;
        try c.lockInGuess{value: 1 ether}(hash1) {
            ok1 = true;
        } catch {
            ok1 = false;
        }
        // In the reference, this succeeds: ok1 == true.
        // In the buggy version (requires block != 0) it reverts: ok1 == false.
        // So we assert the reference holds: ok1 == true (reference succeeds).
        assertTrue(ok1);
    }
}

