        vm.roll(1);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(blockhash(1))));

        // Move to block 2 (the guess block stored is block.number + 1 = 2)
        vm.roll(2);

