        // but require(block.number >= guessed block) succeeds in buggy version
        bool ok;
        vm.prank(user);
        try c.settle() { ok = true; } catch { ok = false; }

        // Reference version reverts (ok == false) because block.number > guessed block is false
        // Buggy version does NOT revert (ok == true) and may transfer ether (but blockhash(2) is 0 at block 2, so guess == 0 fails, no transfer)
        // The key observable divergence: in reference, settle reverts; in buggy, it does not.
        assertTrue(ok == false); // reference: true (settle reverts), buggy: false (settle succeeds)
    }
}

