import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Fund the player with 1 ether to lock in a guess
        address player = address(0x1234);
        vm.deal(player, 2 ether);
        vm.startPrank(player);
        c.lockInGuess{value: 1 ether}(keccak256("anything"));
        vm.stopPrank();

        // Warp to the next block after lockInGuess sets block.number+1
        // In lockInGuess, guesses[player].block = block.number + 1
        // So if we were at block N when calling lockInGuess, stored block = N+1
        // We want block.number == stored block, so warp to stored block = N+1
        // But after lockInGuess, the current block.number is N (since lockInGuess executed at block N)
        // We need to warp to block N+1 = stored block
        // Actually lockInGuess ran at block.number = N (say N=1). stored = 2.
        // To make block.number == stored block, warp to block 2.
        vm.roll(2);

        // Now call settle() - the reference has require(guesses[msg.sender].block != 0) which passes (stored=2)
        // then require(block.number > guesses[msg.sender].block) -> 2 > 2 is false, so reference would revert here.
        // But the reference sets block=0 only after this check? No, look: reference first checks block != 0, then block.number > block, then computes, then sets block=0.
        // So reference reverts at the second require, NOT reaching the block=0 reset.
        // The modified version instead has require(guesses[msg.sender].block == 0) which fails because block is 2.
        // So both revert but with different revert reasons — we need the assertion to fail on the modified version.
        // We can use try/catch to assert that the call does NOT revert in the reference but DOES revert in the modified? 
        // But both revert! We need an observable difference: maybe we check the balance?
        // Actually, after the call, the reference leaves block=2 (unchanged) and does not transfer, while modified reverts before any state change.
        // Both leave block=2, both don't transfer. There's no divergence in observable state.
        // Let's choose a scenario where block.number > stored block so settle() proceeds further.
        // Better: lockInGuess, then warp beyond stored block, then settle.
        // For the reference: stored block != 0, block.number > stored block, computes answer, if guess == answer then transfer 2 ether.
        // For the modified: stored block == 0? No, stored=2, so first require fails -> revert.
        // So reference may transfer, modified reverts -> divergent on balance.
        // Let's make the guess correct and check player balance.
    }
}

